import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Comma_002dSeparated-Value-Output-Options.md","filePath":"manual-en/Comma_002dSeparated-Value-Output-Options.md","lastUpdated":1785684581000}'),p={name:"manual-en/Comma_002dSeparated-Value-Output-Options.md"};function n(i,e,r,l,u,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h3 id="_3-8-comma-separated-value-output-options" tabindex="-1">3.8 Comma-Separated Value Output Options <a class="header-anchor" href="#_3-8-comma-separated-value-output-options" aria-label="Permalink to &quot;3.8 Comma-Separated Value Output Options&quot;">​</a></h3><p>To produce output in comma-separated value (CSV) format, specify -o file on the PSPP command line, optionally followed by any of the options shown in the table below to customize the output format.</p><p>-O format=csv</p><p>Specify the output format. This is only necessary if the file name given on -o does not end in .csv.</p><p>-O separator=field-separator</p><p>Sets the character used to separate fields. Default: a comma (‘,’).</p><p>-O quote=qualifier</p><p>Sets qualifier as the character used to quote fields that contain white space, the separator (or any of the characters in the separator, if it contains more than one character), or the quote character itself. If qualifier is longer than one character, only the first character is used; if qualifier is the empty string, then fields are never quoted.</p><p>-O titles=boolean</p><p>Whether table titles (brief descriptions) should be printed. Default: <code>on</code>.</p><p>-O captions=boolean</p><p>Whether table captions (more extensive descriptions) should be printed. Default: on.</p><p>The CSV format used is an extension to that specified in RFC 4180:</p><p>Tables</p><p>Each table row is output on a separate line, and each column is output as a field. The contents of a cell that spans multiple rows or columns is output only for the top-left row and column; the rest are output as empty fields.</p><p>Titles</p><p>When a table has a title and titles are enabled, the title is output just above the table as a single field prefixed by ‘Table:’.</p><p>Captions</p><p>When a table has a caption and captions are enabled, the caption is output just below the table as a single field prefixed by ‘Caption:’.</p><p>Footnotes</p><p>Within a table, footnote markers are output as bracketed letters following the cell’s contents, <em>e.g.</em> ‘[a]’, ‘[b]’, ... The footnotes themselves are output following the body of the table, as a separate two-column table introduced with a line that says ‘Footnotes:’. Each row in the table represent one footnote: the first column is the marker, the second column is the text.</p><p>Text</p><p>Text in output is printed as a field on a line by itself. The TITLE and SUBTITLE produce similar output, prefixed by ‘Title:’ or ‘Subtitle:’, respectively.</p><p>Messages</p><p>Errors, warnings, and notes are printed the same way as text.</p><p>Charts</p><p>Charts are not included in CSV output.</p><p>Successive output items are separated by a blank line.</p>',28)])])}const m=t(p,[["render",n]]);export{h as __pageData,m as default};
